#include <utility>

template <typename T>
class Box
{
public:
    explicit Box(T value) : m_value{ std::move(value) } {}
    const T& get() const { return m_value; }
    void set(T value) { m_value = std::move(value); }

private:
    T m_value{};
};

unitTests:
TEST("a box of int") { Box<int> b{ 5 }; CHECK_EQ(b.get(), 5); b.set(9); CHECK_EQ(b.get(), 9); }
TEST("a box of string") { Box<std::string> b{ "hello" }; CHECK_EQ(b.get(), "hello"); b.set("bye"); CHECK_EQ(b.get(), "bye"); }
TEST("the compiler can work out T") { const Box b{ 2.5 }; static_assert(std::is_same_v<decltype(b), const Box<double>>); CHECK_NEAR(b.get(), 2.5, 1e-12); }
TEST("get returns a reference, not a copy") { const Box<std::string> b{ "x" }; CHECK(&b.get() == &b.get()); }

